import{_ as o,o as t,c as a,ae as i}from"./chunks/framework.YL6nI5ZP.js";const p=JSON.parse('{"title":"How to Troubleshoot Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/07-troubleshoot.md","filePath":"how-to/07-troubleshoot.md"}'),r={name:"how-to/07-troubleshoot.md"};function s(n,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="how-to-troubleshoot-local-swmm" tabindex="-1">How to Troubleshoot Local SWMM <a class="header-anchor" href="#how-to-troubleshoot-local-swmm" aria-label="Permalink to &quot;How to Troubleshoot Local SWMM&quot;">​</a></h1><p>Fix common problems with the map, runs, the WASM build, and the WebGPU path, and learn the known gotchas of this codebase.</p><h2 id="how-to-fix-a-blank-map-no-tiles" tabindex="-1">How to fix a blank map / no tiles <a class="header-anchor" href="#how-to-fix-a-blank-map-no-tiles" aria-label="Permalink to &quot;How to fix a blank map / no tiles&quot;">​</a></h2><ul><li><code>public/config.js</code> missing or token empty → create it with a valid <code>MAPBOX_ACCESS_TOKEN</code> (see <a href="./02-configure">How to Configure Local SWMM</a>).</li><li>Browser blocked by CSP? Check the console for CSP violations against <code>api.mapbox.com</code>.</li></ul><h2 id="how-to-fix-run-errors-immediately-with-a-warning" tabindex="-1">How to fix &quot;Run&quot; errors immediately with a warning <a class="header-anchor" href="#how-to-fix-run-errors-immediately-with-a-warning" aria-label="Permalink to &quot;How to fix &quot;Run&quot; errors immediately with a warning&quot;">​</a></h2><ul><li>Cause: no nodes, no outfall, or <strong>US units with a 2D mesh</strong> (2D is SI-only) — <code>app.js:1402-1406</code>.</li><li>Fix: add at least one node and one <code>OUTFALL</code>; switch units to SI if a 2D mesh is present.</li></ul><h2 id="how-to-fix-a-simulation-that-fails-silently-with-engine-errors" tabindex="-1">How to fix a simulation that fails silently / with engine errors <a class="header-anchor" href="#how-to-fix-a-simulation-that-fails-silently-with-engine-errors" aria-label="Permalink to &quot;How to fix a simulation that fails silently / with engine errors&quot;">​</a></h2><ol><li>Check the <strong>Run Status</strong> window, then the <strong>Report</strong> tab. For deep diagnostics, the worker dumps the <code>.rpt</code> error lines and the first 3000 chars of the INP on failure (<code>openSwmm2dWorker.js:109-148</code>).</li><li>Reproduce in Node: <code>node scripts/run-engine-marcher.mjs model.inp out.json</code> prints engine codes (<code>SWMM_ERR_LIFECYCLE = 6</code> is the &quot;natural completion&quot; code).</li></ol><h2 id="how-to-fix-a-wasm-build-failing-at-pluginfactory-cpp-46-unsupported-platform" tabindex="-1">How to fix a WASM build failing at <code>PluginFactory.cpp:46: unsupported platform</code> <a class="header-anchor" href="#how-to-fix-a-wasm-build-failing-at-pluginfactory-cpp-46-unsupported-platform" aria-label="Permalink to &quot;How to fix a WASM build failing at `PluginFactory.cpp:46: unsupported platform`&quot;">​</a></h2><ul><li>Cause: the submodule was re-pinned without the wasm-compat commit.</li><li>Fix: restore <code>85e4be38</code> (see <a href="./03-build-from-source">How to Build the WASM Engine from Source</a>, section 5) or re-apply the Emscripten no-ops.</li></ul><h2 id="how-to-fix-could-not-find-zip-during-vcpkg-bootstrap" tabindex="-1">How to fix <code>Could not find zip</code> during vcpkg bootstrap <a class="header-anchor" href="#how-to-fix-could-not-find-zip-during-vcpkg-bootstrap" aria-label="Permalink to &quot;How to fix `Could not find zip` during vcpkg bootstrap&quot;">​</a></h2><ul><li>Cause: missing system <code>zip</code>/<code>unzip</code>/<code>tar</code>.</li><li>Fix: on Arch: <code>sudo pacman -S zip unzip tar</code>.</li></ul><h2 id="how-to-handle-a-2d-run-that-falls-back-to-wasm" tabindex="-1">How to handle a 2D run that falls back to WASM <a class="header-anchor" href="#how-to-handle-a-2d-run-that-falls-back-to-wasm" aria-label="Permalink to &quot;How to handle a 2D run that falls back to WASM&quot;">​</a></h2><ul><li>Cause: <code>navigator.gpu</code> absent or <code>maxStorageBuffersPerShaderStage &lt; 16</code> (e.g. Apple Silicon/Metal).</li><li>Fix: none needed — this is expected; the WASM path is the reference.</li></ul><h2 id="how-to-fix-mesh-generation-failures-on-huge-domains" tabindex="-1">How to fix mesh generation failures on huge domains <a class="header-anchor" href="#how-to-fix-mesh-generation-failures-on-huge-domains" aria-label="Permalink to &quot;How to fix mesh generation failures on huge domains&quot;">​</a></h2><ul><li>The Triangle WASM heap is fixed at 16 MB; the budget caps (<code>trianglePointBudget=8000</code>, <code>autoAreaCap</code>) kick in automatically. Reduce domain area or minAngle.</li></ul><h2 id="how-to-fix-stale-wasm-being-served" tabindex="-1">How to fix stale wasm being served <a class="header-anchor" href="#how-to-fix-stale-wasm-being-served" aria-label="Permalink to &quot;How to fix stale wasm being served&quot;">​</a></h2><ul><li>The server sends <code>Cache-Control: no-store</code>, but if you&#39;re hosting elsewhere, hard-refresh after rebuilding (<code>swmm6wasm.js?v=&lt;n&gt;</code> query params are used at <code>index.html:790-810</code>).</li></ul><h2 id="how-to-fix-fixture-files-missing-for-webgpu-scripts" tabindex="-1">How to fix fixture files missing for WebGPU scripts <a class="header-anchor" href="#how-to-fix-fixture-files-missing-for-webgpu-scripts" aria-label="Permalink to &quot;How to fix fixture files missing for WebGPU scripts&quot;">​</a></h2><ul><li>Regenerate: <code>node scripts/make-marcher-inp.mjs …</code> / <code>node scripts/make-marcher-cpl-inp.mjs …</code> or run <code>verify-bellinge.mjs</code> once to populate <code>scripts/verify-out/</code>.</li></ul><h2 id="known-gotchas-oddities" tabindex="-1">Known gotchas &amp; oddities <a class="header-anchor" href="#known-gotchas-oddities" aria-label="Permalink to &quot;Known gotchas &amp; oddities&quot;">​</a></h2><ol><li><strong>README drift:</strong> README Quick Start says <code>cd SWMM_3D_Web_UI</code> and <code>http://localhost:8000</code>; the actual dir is <code>LocalSWMM</code> and the port is <code>8080</code>.</li><li><strong>Two identical engine binaries</strong> (<code>openswmm2d.*</code> and <code>swmm6wasm.*</code>) are byte-for-byte copies — keep them in sync (the build script does).</li><li><strong><code>simWorker</code> progress messages are dead protocol:</strong> the worker never posts them and <code>app.js:1275</code> ignores them; the 1D progress bar is a time-based cosmetic.</li><li><strong><code>.out</code> parsing is 1D-only:</strong> the 2D path carries per-frame JS arrays instead and explicitly nulls <code>App.outData</code> (<code>app.js:1443</code>).</li><li><strong><code>bench-1d.mjs</code> carries a stale &quot;probe-1d.mjs&quot; header comment.</strong></li><li><strong>Windows-only hard-coding</strong> in <code>bench-gpu-coupl.mjs</code> and <code>run-webgpu-harness.mjs</code> (hard-coded Chrome path).</li><li><strong>LID layer parameters are parsed but not stored</strong> (<code>inpParser.js:411-424</code>) — LID round-trips rely on <code>rawSections</code>.</li><li><strong>CI <code>config.js</code> uses <code>const CONFIG</code></strong> while local configs use <code>var</code>; <code>window.CONFIG</code> lookups (<code>app.js:446</code>) are defensive either way.</li><li><strong>The <code>harness.html</code> &quot;lessons&quot;</strong> document historical VARIABLE_STEP pinning that was later proven wrong — read the 2026-08-06 entries in <code>WEBGPU_PLAN.md</code> before &quot;fixing&quot; anything in <code>couplingSplit.js</code>.</li><li><strong>Vertex-coupled live head reconstruction</strong> (<code>stCnt&gt;0</code>) exists in the WGSL kernel but the split clears stencil pointers — the live path uses the lowest-bed cell head.</li><li><strong>NATURAL_NEIGHBOUR rainfall</strong> is not modelled by the marcher (uniform gage mean only).</li><li><strong>vcpkg manifest layering:</strong> the engine&#39;s own <code>vcpkg.json</code> is ignored for the wasm build; only the root manifest applies.</li></ol>',22)])])}const m=o(r,[["render",s]]);export{p as __pageData,m as default};
